    def merge_intervals(intervals):
        if not intervals:
            return []

        # Filter out empty intervals and sort
        valid = [interval for interval in intervals if interval[0] < interval[1]]
        if not valid:
            return []

        valid.sort()
        merged = [valid[0]]

        for start, end in valid[1:]:
            if start <= merged[-1][1]:
                # Overlapping or touching, merge
                merged[-1][1] = max(merged[-1][1], end)
            else:
                # Non-overlapping
                merged.append([start, end])

        return merged

    # Merge intervals in a and b
    merged_a = merge_intervals(a)
    merged_b = merge_intervals(b)

    if not merged_a:
        return []
    if not merged_b:
